const apiSecret = 'IKxxQL7zniUB5s9TeijsChM8hAs';
const timestamp = Math.floor(Date.now() / 1000);
const folder = 'n8n_wf10_runway';

// upload用の署名生成（パラメータ: folder, timestamp）
const stringToSign = `folder=${folder}&timestamp=${timestamp}${apiSecret}`;

// SHA-1ハッシュ生成（WF7のロジックを流用）
function sha1(str) {
  function rotateLeft(n, s) {
    return (n << s) | (n >>> (32 - s));
  }

  function toHexStr(n) {
    let s = '', v;
    for (let i = 7; i >= 0; i--) {
      v = (n >>> (i * 4)) & 0xf;
      s += v.toString(16);
    }
    return s;
  }

  function utf8Encode(str) {
    return unescape(encodeURIComponent(str));
  }

  let message = utf8Encode(str);
  let msgLen = message.length;
  let words = [];

  for (let i = 0; i < msgLen; i++) {
    words[i >>> 2] |= (message.charCodeAt(i) & 0xff) << (24 - 8 * (i % 4));
  }

  words[msgLen >>> 2] |= 0x80 << (24 - 8 * (msgLen % 4));
  words[(((msgLen + 8) >>> 6) << 4) + 15] = msgLen * 8;

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  for (let i = 0; i < words.length; i += 16) {
    let w = words.slice(i, i + 16);
    for (let j = 16; j < 80; j++) {
      w[j] = rotateLeft(w[j-3] ^ w[j-8] ^ w[j-14] ^ w[j-16], 1);
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4;

    for (let j = 0; j < 80; j++) {
      let f, k;
      if (j < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (j < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (j < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }

      let temp = (rotateLeft(a, 5) + f + e + k + (w[j] | 0)) | 0;
      e = d;
      d = c;
      c = rotateLeft(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  return toHexStr(h0) + toHexStr(h1) + toHexStr(h2) + toHexStr(h3) + toHexStr(h4);
}

const signature = sha1(stringToSign);

// 台本も受け渡し
const prompt = $('Set - Test Data').first().json.台本本文;

return {
  cloudinary_timestamp: timestamp,
  cloudinary_signature: signature,
  cloudinary_folder: folder,
  prompt: prompt
};

// n8nのヘルパー関数を使用してバイナリデータを取得
try {
  const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');

  // Base64エンコード
  const base64Data = binaryData.toString('base64');

  // バイナリデータのMIMEタイプを取得
  const mimeType = $binary.data.mimeType || 'image/png';

  // Data URI形式に変換
  const dataUri = `data:${mimeType};base64,${base64Data}`;

  // Cloudinary認証情報
  const cloudName = 'drzmodro8';
  const apiKey = '188947963992381';
  const timestamp = $json.cloudinary_timestamp;
  const signature = $json.cloudinary_signature;
  const folder = $json.cloudinary_folder;

  // Cloudinary Upload APIを呼び出し
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.cloudinary.com/v1_1/${cloudName}/image/upload`,
    headers: {
      'Content-Type': 'application/json'
    },
    body: {
      file: dataUri,
      folder: folder,
      timestamp: timestamp,
      api_key: apiKey,
      signature: signature
    },
    json: true
  });

  // promptを受け渡し
  return {
    json: {
      ...response,
      prompt: $json.prompt
    }
  };

} catch (error) {
  // 詳細なエラー情報を返す
  return {
    json: {
      error: error.message,
      error_details: error.response?.data || error.response || 'No response data',
      status_code: error.response?.status || 'unknown',
      cloudinary_timestamp: $json.cloudinary_timestamp,
      cloudinary_signature: $json.cloudinary_signature
    }
  };
}
